340	     * @return the normalised address, or the empty string if {@code value} is
341	     *         {@code null} or blank
342	     */
343	    public static String normalizeAddress(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
348	        if (collapsed.isEmpty()) {
349	            return "";
350	        }
351	        String[] tokens = collapsed.split(" ");
352	        for (int i = 0; i < tokens.length; i++) {
353	            tokens[i] = switch (tokens[i]) {
354	                case "ST" -> "STREET";
355	                case "RD" -> "ROAD";
356	                case "AVE" -> "AVENUE";
357	                default -> tokens[i];
358	            };
359	        }
360	        return String.join(" ", tokens);
361	    }
