57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (!normalizeNewOwner(owner)) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (dailyLimitReached(owner.getRegistrationDate())) {
118	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
119	        }
120	        if (cityIsAtCapacity(owner.getCity())) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        Optional<Owner> householdMember = findHouseholdMember(owner);
124	        if (householdMember.isPresent() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
125	            joinHousehold(owner, householdMember.get());
126	        }
127	        if (identityKeyAlreadyUsed(owner)) {
128	            return new ResponseEntity<>(HttpStatus.CONFLICT);
129	        }
130	        assignDerivedAttributes(owner);
131	        this.clinicService.saveOwner(owner);
132	        auditOwnerCreated(owner);
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        headers.setLocation(UriComponentsBuilder.newInstance()
135	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
136	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
151	        String email = ownerFieldsDto.getEmail();
152	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        this.clinicService.deleteOwner(owner);
166	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        HttpHeaders headers = new HttpHeaders();
177	        Pet pet = petMapper.toPet(petFieldsDto);
178	        owner.setId(ownerId);
179	        pet.setOwner(owner);
180	        pet.getType().setName(null);
181	        this.clinicService.savePet(pet);
182	        PetDto petDto = petMapper.toPetDto(pet);
183	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
184	            .buildAndExpand(pet.getId()).toUri());
185	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner != null) {
193	            Pet currentPet = this.clinicService.findPetById(petId);
194	            if (currentPet != null) {
195	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
196	                currentPet.setName(petFieldsDto.getName());
197	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
198	                this.clinicService.savePet(currentPet);
199	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	            }
201	        }
202	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
208	        HttpHeaders headers = new HttpHeaders();
209	        Visit visit = visitMapper.toVisit(visitFieldsDto);
210	        Pet pet = new Pet();
211	        pet.setId(petId);
212	        visit.setPet(pet);
213	        this.clinicService.saveVisit(visit);
214	        VisitDto visitDto = visitMapper.toVisitDto(visit);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
216	            .buildAndExpand(visit.getId()).toUri());
217	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
218	    }
219	
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner != null) {
226	            Pet pet = owner.getPet(petId);
227	            if (pet != null) {
228	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	
234	    /**
235	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
236	     * the canonical form each stored value must take: the address is trimmed,
237	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
238	     * telephone is converted to E.164, any email is lower-cased and a missing
239	     * registration date defaults to today. Field-level rejections are reported here
240	     * rather than inline in {@link #addOwner}, and normalisation runs before any
241	     * household comparison so those comparisons see the canonical values.
242	     *
243	     * @param owner the freshly-mapped owner to normalise
244	     * @return {@code true} if the fields are valid, or {@code false} if the address
245	     *         is blank after normalisation, the telephone cannot form a valid
246	     *         E.164 number, or a supplied registration date is later than the
247	     *         server date, in which case the request must be rejected with
248	     *         {@code 400 Bad Request}
249	     */
250	    private boolean normalizeNewOwner(Owner owner) {
251	        String address = Owner.normalizeAddress(owner.getAddress());
252	        if (address.isEmpty()) {
253	            return false;
254	        }
255	        owner.setAddress(address);
256	        String telephone = toE164(owner.getTelephone());
257	        if (telephone == null) {
258	            return false;
259	        }
260	        owner.setTelephone(telephone);
261	        if (owner.getEmail() != null) {
262	            owner.setEmail(owner.getEmail().toLowerCase());
263	        }
264	        if (!owner.postcodeValidForLocality()) {
265	            return false;
266	        }
267	        if (owner.getRegistrationDate() == null) {
268	            owner.setRegistrationDate(LocalDate.now());
269	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
270	            return false;
271	        }
272	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
273	        return true;
274	    }
275	
276	    /**
277	     * Roll the given date forward to the next business day when it falls on a
278	     * weekend: a Saturday or Sunday is advanced to the following Monday, while a
279	     * weekday is returned unchanged. Applied to the effective registration date
280	     * (whether supplied in the request or defaulted to the server date) so that
281	     * every value derived from it uses the adjusted business day.
282	     *
283	     * @param date the effective registration date
284	     * @return the same date if it is a weekday, otherwise the next Monday
285	     */
286	    private static LocalDate rollToBusinessDay(LocalDate date) {
287	        switch (date.getDayOfWeek()) {
288	            case SATURDAY:
289	                return date.plusDays(2);
290	            case SUNDAY:
291	                return date.plusDays(1);
292	            default:
293	                return date;
294	        }
295	    }
296	
297	    /**
298	     * Determine whether the candidate owner's identity key collides with any existing
299	     * owner's. This is the single, consolidated duplicate check: it subsumes the
300	     * former separate telephone, email and household checks by comparing the whole
301	     * derived {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty)
302	     * + '|' + householdId}). Only an exact full-key match is a duplicate, so two owners
303	     * that agree on some — but not all — of the key's parts (for example two members of
304	     * the same household with different telephones) are not duplicates. Evaluated after
305	     * normalisation and household resolution, so the candidate's key reflects its
306	     * canonical field values and any household it has joined.
307	     *
308	     * @param owner the candidate owner being created, after household resolution
309	     * @return {@code true} if an existing owner has the same identity key
310	     */
311	    private boolean identityKeyAlreadyUsed(Owner owner) {
312	        String identityKey = owner.getIdentityKey();
313	        return this.clinicService.findAllOwners().stream()
314	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
315	    }
316	
317	    /**
318	     * Find an existing owner that belongs to the same household as the given owner,
319	     * i.e. shares the same last name and address (compared case-insensitively with
320	     * runs of whitespace collapsed to a single space).
321	     *
322	     * @param owner the candidate owner being created
323	     * @return the matching existing owner, or empty if none exists
324	     */
325	    private Optional<Owner> findHouseholdMember(Owner owner) {
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> existing.sameHouseholdAs(owner))
328	            .findFirst();
329	    }
330	
331	    /**
332	     * Assign the joining owner and an existing household member the same stable
333	     * household identifier. The identifier is derived deterministically from the
334	     * shared household key (last name + address, normalised), so every owner in a
335	     * household resolves to the same value; the existing member is updated when it
336	     * does not already carry it.
337	     *
338	     * @param owner    the owner being created
339	     * @param existing an existing owner in the same household
340	     */
341	    private void joinHousehold(Owner owner, Owner existing) {
342	        String householdId = UUID
343	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
344	        owner.setHouseholdId(householdId);
345	        if (!householdId.equals(existing.getHouseholdId())) {
346	            existing.setHouseholdId(householdId);
347	            this.clinicService.saveOwner(existing);
348	        }
349	    }
350	
351	    /**
352	     * Assign the owner's computed-at-creation attributes in place: its customer code,
353	     * namesake count, membership number, bulk-signup warning and household size. Unlike
354	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
355	     * derived once here — from the owner's own (already normalised) fields and from the
356	     * wider owner population — and persisted with the owner. Run after normalisation,
357	     * household resolution and the identity-key check, so every value reflects the
358	     * owner's final field values and any household it has joined, and immediately before
359	     * the owner is saved.
360	     *
361	     * <p>Ordering matters: the customer code is assigned first because the membership
362	     * number is built from it.
363	     *
364	     * @param owner the candidate owner being created, after household resolution
365	     */
366	    private void assignDerivedAttributes(Owner owner) {
367	        owner.setCustomerCode(customerCode(owner));
368	        owner.setNamesakeCount(countNamesakes(owner));
369	        owner.setMembershipNumber(membershipNumber(owner));
370	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
371	        owner.setHouseholdSize(householdSize(owner));
372	    }
373	
374	    /**
375	     * Count how many owners belong to the given owner's household once this create
376	     * completes: the owners that already share its {@code householdId} plus the owner
377	     * being created. Evaluated after any {@link #joinHousehold(Owner, Owner)} has run,
378	     * so the household identifier (and any existing member updated to it) is already in
379	     * place. An owner that has not joined a household (no {@code householdId}) is a
380	     * household of one.
381	     *
382	     * @param owner the candidate owner being created, after household resolution
383	     * @return the household member count after this create (at least {@code 1})
384	     */
385	    private int householdSize(Owner owner) {
386	        String householdId = owner.getHouseholdId();
387	        if (householdId == null) {
388	            return 1;
389	        }
390	        long existing = this.clinicService.findAllOwners().stream()
391	            .filter(other -> householdId.equals(other.getHouseholdId()))
392	            .count();
393	        return (int) existing + 1;
394	    }
395	
396	    /**
397	     * Count the existing owners that share the given owner's first and last name,
398	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
399	     * before the new owner is saved, so the result reflects only owners that
400	     * already existed at creation time.
401	     *
402	     * @param owner the candidate owner being created
403	     * @return the number of existing namesakes
404	     */
405	    private int countNamesakes(Owner owner) {
406	        String firstName = normalizeName(owner.getFirstName());
407	        String lastName = normalizeName(owner.getLastName());
408	        return (int) this.clinicService.findAllOwners().stream()
409	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
410	                && normalizeName(existing.getLastName()).equals(lastName))
411	            .count();
412	    }
413	
414	    private static String normalizeName(String value) {
415	        return value == null ? "" : value.trim().toLowerCase();
416	    }
417	
418	    /**
419	     * Determine whether the given city has already reached its owner capacity, i.e.
420	     * it already contains 50 or more existing owners (compared case-insensitively
421	     * with surrounding whitespace trimmed). A new owner may not be created in a city
422	     * that is at capacity.
423	     *
424	     * @param city the candidate owner's city
425	     * @return {@code true} if the city already holds 50 or more owners
426	     */
427	    private boolean cityIsAtCapacity(String city) {
428	        String normalizedCity = normalizeName(city);
429	        long count = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
431	            .count();
432	        return count >= 50;
433	    }
434	
435	    /**
436	     * Determine whether the daily owner-creation limit has already been reached, i.e.
437	     * 100 or more owners already carry the given registration date. A new owner may
438	     * not be created once that day's cap is reached.
439	     *
440	     * @param registrationDate the registration date the new owner would be created with
441	     * @return {@code true} if 100 or more existing owners share that registration date
442	     */
443	    private boolean dailyLimitReached(LocalDate registrationDate) {
444	        long count = this.clinicService.findAllOwners().stream()
445	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
446	            .count();
447	        return count >= 100;
448	    }
449	
450	    /**
451	     * Determine whether more than 80 owners have already been created for the given
452	     * registration date, i.e. strictly more than 80 existing owners carry that date.
453	     * Evaluated before the new owner is saved, so it reflects only owners that
454	     * already existed at creation time.
455	     *
456	     * @param registrationDate the registration date the new owner would be created with
457	     * @return {@code true} if more than 80 existing owners share that registration date
458	     */
459	    private boolean bulkSignupWarning(LocalDate registrationDate) {
460	        long count = this.clinicService.findAllOwners().stream()
461	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
462	            .count();
463	        return count > 80;
464	    }
465	
466	    /**
467	     * Build the customer code assigned to the given owner, formatted
468	     * {@code <REGION>-<HASH8>}: REGION is the canonical region derived for the owner
469	     * (see {@link Owner#regionForOwner()}, the postcode-then-city region also exposed
470	     * as its {@link Owner#getLocality() locality}) and HASH8 is the first eight
471	     * upper-case hexadecimal characters of the SHA-256 digest of the owner's
472	     * normalised telephone concatenated with its last name (e.g.
473	     * {@code NSW-9F86D081}). The whole owner is passed so the code can be derived from
474	     * whichever of its (already normalised) fields the identity scheme requires.
475	     *
476	     * @param owner the owner being created, with its fields already normalised
477	     * @return the assigned customer code
478	     */
479	    private String customerCode(Owner owner) {
480	        String region = owner.regionForOwner();
481	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
482	        return String.format("%s-%s", region, hash8);
483	    }
484	
485	    /**
486	     * The first eight upper-case hexadecimal characters of the SHA-256 digest of the
487	     * UTF-8 bytes of the given value.
488	     */
489	    private static String sha256Hex8(String value) {
490	        try {
491	            byte[] digest = MessageDigest.getInstance("SHA-256")
492	                .digest(value.getBytes(StandardCharsets.UTF_8));
493	            StringBuilder hex = new StringBuilder();
494	            for (byte b : digest) {
495	                hex.append(String.format("%02X", b));
496	                if (hex.length() >= 8) {
497	                    break;
498	                }
499	            }
500	            return hex.substring(0, 8);
501	        } catch (NoSuchAlgorithmException e) {
502	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
503	        }
504	    }
505	
506	    /**
507	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
508	     * one place so it stays in step with the owner's identity: it reports the assigned
509	     * customer code alongside the owner's id, registration date and membership level.
510	     *
511	     * @param owner the owner that has just been created and saved
512	     */
513	    private void auditOwnerCreated(Owner owner) {
514	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
515	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
516	    }
517	
518	    /**
519	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
520	     * where {@code <customerCode>} is the owner's already-assigned customer code and
521	     * YY is the last two digits of the registration date's year (e.g.
522	     * {@code NSW-9F86D081-M26}). Evaluated after the customer code and registration date
523	     * have been set.
524	     *
525	     * @param owner the owner being created, with customer code and registration date
526	     *              already assigned
527	     * @return the assigned membership number
528	     */
529	    private String membershipNumber(Owner owner) {
530	        int yy = owner.getRegistrationDate().getYear() % 100;
531	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
532	    }
533	
534	    /**
535	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
536	     * code when present, otherwise assume country code '+61' and drop a single
537	     * leading '0' from the national digits. Spaces, dashes and brackets are
538	     * stripped. The result must contain 8 to 15 digits after the '+'.
539	     *
540	     * <p>In addition, the national-number length is validated against the country
541	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
542	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
543	     * whose national-number length is wrong for its country code is rejected.
544	     *
545	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
546	     *         input cannot form a valid E.164 number.
547	     */
548	    private static String toE164(String raw) {
549	        if (raw == null) {
550	            return null;
551	        }
552	        String cleaned = raw.replaceAll("[\\s()-]", "");
553	        String digits;
554	        if (cleaned.startsWith("+")) {
555	            digits = cleaned.substring(1);
556	        } else {
557	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
558	            digits = "61" + national;
559	        }
560	        if (!digits.matches("\\d{8,15}")) {
561	            return null;
562	        }
563	        if (!nationalNumberLengthValid(digits)) {
564	            return null;
565	        }
566	        return "+" + digits;
567	    }
568	
569	    /**
570	     * Validate the length of the national number (the digits after the country
571	     * code) against the country code carried by the given E.164 digit string: a
572	     * {@code 61} (Australia) number requires exactly 9 national digits and a
573	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
574	     * without a pinned length are accepted (only the generic 8-15 digit rule
575	     * applies to them).
576	     *
577	     * @param digits the E.164 digits without the leading '+'
578	     * @return {@code true} if the national-number length is correct for the country
579	     */
580	    private static boolean nationalNumberLengthValid(String digits) {
581	        if (digits.startsWith("61")) {
582	            return digits.length() - 2 == 9;
583	        }
584	        if (digits.startsWith("1")) {
585	            return digits.length() - 1 == 10;
586	        }
587	        return true;
588	    }
589	}
